using System.ClientModel;
using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations ---

var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(
    (string query) =>
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        return SearchWeb(query);
    },
    "search_web",
    "Searches the web for a query and returns relevant result snippets. Use this to find information about a topic.");

var addNoteTool = AIFunctionFactory.Create(
    ([Description("A concise note summarizing a key finding")] string note) =>
    {
        notebook.Add(note);
        Console.WriteLine($"  📝 Note added ({notebook.Count} total)");
        return $"Note saved. You now have {notebook.Count} note(s).";
    },
    "add_note",
    "Saves a research note. Use this to record important findings as you research.");

var readNotesTool = AIFunctionFactory.Create(
    () =>
    {
        if (notebook.Count == 0) return "No notes yet.";
        return string.Join("\n", notebook.Notes.Select((n, i) => $"{i + 1}. {n}"));
    },
    "read_notes",
    "Reads all saved research notes. Use this to review what you've found so far before writing a summary.");

// --- Chat client setup ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set OPENAI_API_KEY or AZURE_OPENAI_API_KEY environment variable.");

var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

OpenAIClient openAIClient = endpoint is not null
    ? new AzureOpenAIClient(new Uri(endpoint), new ApiKeyCredential(apiKey))
    : new OpenAIClient(new ApiKeyCredential(apiKey));

IChatClient chatClient = openAIClient
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

// --- Agent loop ---

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        🔬 Research Agent             ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.Write("\nEnter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: \"{topic}\"\n");

var tools = new ChatOptions
{
    Tools = [searchTool, addNoteTool, readNotesTool],
    Temperature = 0.3f,
};

List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the given topic and produce a well-organized summary.

        Follow these steps:
        1. Search the web 2-3 times with different queries to gather diverse information.
        2. After each search, use add_note to save the most important findings.
        3. Once you have enough notes, use read_notes to review everything.
        4. Finally, write a comprehensive summary with sections and key takeaways.

        Be thorough but concise. Cite specific facts and figures when available.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}"),
];

var response = await chatClient.GetResponseAsync(messages, tools);
Console.WriteLine("\n══════════════════════════════════════");
Console.WriteLine("📋 RESEARCH SUMMARY");
Console.WriteLine("══════════════════════════════════════\n");
Console.WriteLine(response.Text);

// --- Helpers ---

static string SearchWeb(string query)
{
    // Simulated web search results for demonstration.
    // Replace with a real search API (Bing, Google, Brave) for production use.
    var results = new[]
    {
        new { Title = $"Overview of {query}", Snippet = $"A comprehensive overview: {query} is a rapidly evolving area with significant developments in recent years. Key advances include improved efficiency, broader adoption, and new frameworks." },
        new { Title = $"Recent developments in {query}", Snippet = $"Recent news: Researchers have made breakthroughs in {query}, with studies showing a 40% improvement in key metrics over the past year. Industry adoption has grown significantly." },
        new { Title = $"{query} - Expert analysis", Snippet = $"Expert opinion: Leading experts suggest that {query} will continue to grow, with projected market size reaching $50B by 2028. Challenges include scalability and regulation." },
    };
    return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
}

